const base = "http://172.19.0.2:8181/mcp";
const headers = { "content-type": "application/json", "accept": "application/json, text/event-stream" };

// 1. initialize
const initRes = await fetch(base, {
  method: "POST",
  headers,
  body: JSON.stringify({
    jsonrpc: "2.0", id: 1, method: "initialize",
    params: { protocolVersion: "2025-03-26", capabilities: {}, clientInfo: { name: "probe", version: "1.0" } }
  })
});
const sessionId = initRes.headers.get("mcp-session-id");
const initText = await initRes.text();

// 2. initialized notification
await fetch(base, {
  method: "POST",
  headers: { ...headers, ...(sessionId ? { "mcp-session-id": sessionId } : {}) },
  body: JSON.stringify({ jsonrpc: "2.0", method: "notifications/initialized" })
});

// 3. tools/list
const listRes = await fetch(base, {
  method: "POST",
  headers: { ...headers, ...(sessionId ? { "mcp-session-id": sessionId } : {}) },
  body: JSON.stringify({ jsonrpc: "2.0", id: 2, method: "tools/list", params: {} })
});
const listText = await listRes.text();

return { initStatus: initRes.status, sessionId, init: initText.slice(0, 1500), tools: listText.slice(0, 8000) };

