const people = read("/work/model/01-people.dsl");
const systems = read("/work/model/02-systems.dsl");
const rels = read("/work/model/03-relationships.dsl");
const views = read("/work/views/01-views.dsl");
const styles = read("/work/views/02-styles.dsl");

// Inlined equivalent: same as workspace.dsl but with !include expanded and !docs removed
// (the MCP server has the filesystem feature disabled, so it cannot process !docs)
const inlined = `workspace "Acme Platform" "Team architecture model for the Acme order platform" {

    !identifiers hierarchical

    model {
${people}
${systems}
${rels}
    }

    views {
${views}
${styles}
    }
}`;

return { inlined };

