const people = `customer = person "Customer" "A customer who places orders through the web app"
admin = person "Administrator" "An operations staff member who reviews and manages orders"`;

const systems = `platform = softwareSystem "Acme Platform" "Accepts and processes customer orders" {

    webApp = container "Web App" "Single-page application for browsing and ordering" "TypeScript/React" "Web"
    api = container "Order API" "REST API that validates and persists orders" "Go" "Service"
    database = container "Order Database" "System of record for orders" "PostgreSQL 16" "Database"
    queue = container "Event Queue" "Buffers order events for asynchronous processing" "RabbitMQ" "Queue"
    worker = container "Order Worker" "Processes order events for notifications and fulfilment" "Go" "Worker"
}`;

const rels = `customer -> platform.webApp "places orders in" "HTTPS"
admin -> platform.webApp "reviews orders in" "HTTPS"
platform.webApp -> platform.api "calls" "HTTPS/JSON"
platform.api -> platform.database "persists orders in" "SQL"
platform.api -> platform.queue "publishes order events to" "AMQP" "Async"
platform.worker -> platform.queue "consumes order events from" "AMQP" "Async"
platform.worker -> platform.database "updates order status in" "SQL"`;

const views = `systemLandscape "Landscape" {
    include *
    autoLayout
    title "Acme Platform - System Landscape"
}

systemContext platform "Context" {
    include *
    autoLayout
    title "Acme Platform - System Context"
}

container platform "Containers" {
    include *
    autoLayout
    title "Acme Platform - Containers"
}

dynamic platform "OrderFlow" "Placing an order" {
    customer -> platform.webApp "submits an order" "HTTPS"
    platform.webApp -> platform.api "creates the order" "HTTPS/JSON"
    platform.api -> platform.database "persists the order" "SQL"
    platform.api -> platform.queue "publishes an order event" "AMQP"
    platform.worker -> platform.queue "consumes the event" "AMQP"
    platform.worker -> platform.database "updates the order status" "SQL"
    autoLayout
    title "Acme Platform - Order Flow"
}`;

const styles = `styles {
    element "Person" {
        shape Person
        background #08427B
        color #ffffff
    }
    element "Software System" {
        background #1168BD
        color #ffffff
    }
    element "Container" {
        background #438DD5
        color #ffffff
    }
    element "Web" {
        shape WebBrowser
    }
    element "Database" {
        shape Cylinder
    }
    element "Queue" {
        shape Pipe
    }
    element "Worker" {
        shape Robot
    }
    relationship "Relationship" {
        routing Orthogonal
    }
    relationship "Async" {
        style dashed
    }
}`;

const inlined = `workspace "Acme Platform" "Team architecture model for the Acme order platform" {

    !identifiers hierarchical

    model {
${people}

${systems}

${rels}
    }

    views {
${views}

${styles}
    }
}`;

const [parse, validate, inspect] = await Promise.allSettled([
  tools.structurizr.parse({ dsl: inlined }),
  tools.structurizr.validate({ dsl: inlined }),
  tools.structurizr.inspect({ dsl: inlined }),
]);
const fmt = (r) => r.status === "fulfilled" ? r.value : { error: String(r.reason) };
return { parse: fmt(parse), validate: fmt(validate), inspect: fmt(inspect) };

